      "content": "'''Command-line interface for JSON and CSV conversion.'''

from __future__ import annotations

import csv
import sys
from collections.abc import Callable
from typing import TextIO

from converter import csv_to_json, json_to_csv, validate_csv, validate_json

USAGE = '''Usage:
  to-csv INPUT_JSON OUTPUT_CSV
  to-json INPUT_CSV OUTPUT_JSON
  validate json INPUT_PATH
  validate csv INPUT_PATH
'''

_STDOUT: TextIO = sys.stdout
CommandHandler = Callable[[list[str]], int]


def _print_usage() -> None:
    print(USAGE, file=_STDOUT, end='')


def _run_to_csv(args: list[str]) -> int:
    if len(args) != 2:
        _print_usage()
        return 1
    try:
        json_to_csv(args[0], args[1])
    except (OSError, ValueError, csv.Error) as exc:
        print(exc, file=_STDOUT)
        return 1
    return 0


def _run_to_json(args: list[str]) -> int:
    if len(args) != 2:
        _print_usage()
        return 1
    try:
        csv_to_json(args[0], args[1])
    except (OSError, ValueError, csv.Error) as exc:
        print(exc, file=_STDOUT)
        return 1
    return 0


def _run_validate(args: list[str]) -> int:
    if len(args) != 2 or args[0] not in {'json', 'csv'}:
        _print_usage()
        return 1
    try:
        if args[0] == 'json':
            validate_json(args[1])
        else:
            validate_csv(args[1])
    except (OSError, ValueError, csv.Error) as exc:
        print(exc, file=_STDOUT)
        return 1
    print('OK', file=_STDOUT)
    return 0


_COMMANDS: dict[str, CommandHandler] = {
    'to-csv': _run_to_csv,
    'to-json': _run_to_json,
    'validate': _run_validate,
}


def main(argv: list[str] | None = None, *, stdout: TextIO | None = None) -> int:
    '''Run the converter CLI and return an exit code.'''

    global _STDOUT

    previous_stdout = _STDOUT
    _STDOUT = stdout if stdout is not None else sys.stdout
    try:
        args = list(sys.argv[1:] if argv is None else argv)
        if not args:
            _print_usage()
            return 1

        handler = _COMMANDS.get(args[0])
        if handler is None:
            _print_usage()
            return 1
        return handler(args[1:])
    finally:
        _STDOUT = previous_stdout


if __name__ == '__main__':
    raise SystemExit(main())
