import json

import cli


def run_cli(args):
    buffer = io.StringIO()
    code = cli.main(args, stdout=buffer)
    return code, buffer.getvalue()


def test_known_command_is_dispatched(monkeypatch):
    seen = {}

    def fake_handler(args):
        seen['args'] = list(args)
        return 0

    monkeypatch.setitem(cli._COMMANDS, 'to-csv', fake_handler)

    assert cli.main(['to-csv', 'input.json', 'output.csv']) == 0
    assert seen['args'] == ['input.json', 'output.csv']


def test_unknown_command_prints_usage_and_returns_error(capsys):
    assert cli.main(['bogus']) == 1

    output = capsys.readouterr().out
    assert 'Usage:' in output
    assert 'to-csv' in output
    assert 'validate' in output


def test_missing_command_prints_usage(capsys):
    assert cli.main([]) == 1

    output = capsys.readouterr().out
    assert 'Usage:' in output


def test_validate_json_reports_ok_for_valid_input(tmp_path):
    input_json = tmp_path / 'input.json'
    input_json.write_text(json.dumps([{'id': '1'}]), encoding='utf-8')

    code, output = run_cli(['validate', 'json', str(input_json)])

    assert code == 0
    assert output.strip() == 'OK'


def test_validate_json_reports_parse_error_for_invalid_input(tmp_path):
    input_json = tmp_path / 'bad.json'
    input_json.write_text('{not json}', encoding='utf-8')

    code, output = run_cli(['validate', 'json', str(input_json)])

    assert code == 1
    assert 'Expecting' in output
